        {"chinese":"随着科技的发展，我们的生活发生了巨大的变化。","english":"With the development of technology, our lives have changed dramatically.","soundmark":"","grammar":[{"word": "With the development of technology", "role": "A", "label": "状语"}, {"word": "our lives", "role": "S", "label": "主语"}, {"word": "have changed", "role": "V", "label": "谓语"}, {"word": "dramatically", "role": "A", "label": "状语"}]},
